"""Genera vista previa SIN COBROS para revisar agrupación por variantes."""
from pathlib import Path
import csv,json,re,html
root=Path(__file__).resolve().parent.parent
rows=list(csv.DictReader((root/'data/ATLAS_Catalogo_Importacion.csv').open(encoding='utf-8-sig'),delimiter=';'))
group_defs=[
('Arranques','Arranque Rolan · Rendidor original','Rolan','ARR_ROL_'),
('Papel','Papel higiénico Elegante','Elegante','HIG_ELE_'),
('Papel','Rollos de cocina Elegante','Elegante','COC_ELE_'),
('Papel','Bobinas industriales Elegante','Elegante','BOB_ELE_'),
('Papel','Toalla bobina Elegante','Elegante','TOA_ELE_'),
('Papel','Servilletas Elegante','Elegante','SER_ELE_'),
]
groups=[]
for typ,title,brand,prefix in group_defs:
 prods=[]
 for row in rows:
  if row['sku'].startswith(prefix):
   label=row['nombre']
   if prefix=='ARR_ROL_':
    m=re.search(r'\d+x\d+',label)
    label=m.group() if m else label
   else:label=re.sub(r'(?i)\s*Elegante\s*',' ',label).strip()
   prods.append(dict(sku=row['sku'],label=label,base=row['ums_base'],count=int(float(row['ums_por_presentacion'])),present=row['presentacion_compra']))
 groups.append(dict(type=typ,title=title,brand=brand,variants=prods))
assert len(groups)==6 and sum(len(g['variants']) for g in groups)==22
J=json.dumps(groups,ensure_ascii=False).replace('</','<\\/')
page=r'''<!DOCTYPE html><html lang="es-AR"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=5"/><title>JC | Tienda online · Vista previa</title><style>
:root{--red:#c8243f;--ink:#14161b;--line:#e8eaed;--mute:#71767f}*{box-sizing:border-box}body{margin:0;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:var(--ink);background:#fff}button,input{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.notice{background:#15171b;color:#e2e4e7;font-size:11px;text-align:center;padding:9px}.wrap{max-width:1200px;margin:auto;padding:0 29px}.head{position:sticky;top:0;z-index:6;background:#fff;border-bottom:1px solid var(--line)}.headinner{height:76px;display:flex;align-items:center;justify-content:space-between}.logo{font-size:30px;font-weight:950;letter-spacing:-2px}.logo span{color:var(--red)}.logo small{display:block;font-weight:750;font-size:8px;letter-spacing:1.5px}.head button{background:#fff;border:1px solid var(--line);border-radius:9px;padding:12px 17px;font-weight:750;font-size:12px}.hero{display:grid;grid-template-columns:1.3fr .8fr;gap:30px;padding:58px 0 58px}.hero .kicker,.kicker{color:var(--red);font-size:11px;letter-spacing:2px;font-weight:850}.hero h1{font-size:clamp(39px,4.9vw,69px);line-height:1.09;letter-spacing:-3px;margin:17px 0 20px}.hero h1 em{color:var(--red);font-style:normal}.hero p{max-width:530px;color:#737983;font-size:15px;line-height:1.8}.heroart{background:#f2f3f5;border-radius:15px;display:grid;place-items:center;min-height:320px;overflow:hidden}.heroart strong{font-size:175px;font-weight:1000;letter-spacing:-16px;color:#e0e2e6;transform:rotate(-9deg)}.heroart small{position:absolute;color:#adb1b7;font-weight:850;letter-spacing:2px}.sectiontitle{display:flex;align-items:end;justify-content:space-between;gap:15px;margin:26px 0 22px}.sectiontitle h2{font-size:30px;letter-spacing:-1px;margin:11px 0}.sectiontitle span{color:var(--mute);font-size:12px}.filters{display:flex;align-items:center;gap:9px;margin:25px 0}.filters button{border:0;background:#f2f3f5;border-radius:9px;padding:11px 16px;font-size:12px;font-weight:700}.filters button.on{background:var(--ink);color:white}.search{flex:1;padding:14px 16px;border:1px solid var(--line);border-radius:10px;min-width:0;font-size:13px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:70px}.card{border:1px solid var(--line);border-radius:12px;overflow:hidden;min-width:0}.pic{background:linear-gradient(150deg,#f3f4f5,#fafafa);height:200px;display:grid;place-items:center;color:#d0d3d8;font-weight:900;font-size:70px;letter-spacing:-8px}.info{padding:19px}.info .brand{font-size:10px;font-weight:800;color:var(--red);text-transform:uppercase;letter-spacing:1px}.info h3{font-size:19px;letter-spacing:-.3px;min-height:49px;margin:10px 0}.info p{font-size:12px;color:var(--mute)}.info button{display:flex;justify-content:space-between;width:100%;border:0;border-radius:8px;background:var(--ink);color:white;padding:13px;font-size:12px;font-weight:750;margin-top:23px}.footer{background:#17191e;color:white;padding:38px 0}.footer p{font-size:12px;color:#b4b7bb}.overlay{position:fixed;inset:0;z-index:20;background:#10121699;display:none;justify-content:center;align-items:center;padding:15px}.overlay.open{display:flex}.dialog{background:white;max-height:94dvh;overflow:auto;width:min(560px,100%);border-radius:14px;padding:23px}.dialoghead{display:flex;justify-content:space-between;gap:15px;align-items:start}.dialoghead h2{font-size:23px;margin:9px 0 17px}.close{background:#f1f2f3;border:0;border-radius:8px;width:36px;height:36px;font-size:22px}.field{margin:18px 0}.field h4{font-size:12px;margin:10px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.choice,.present{background:white;border:1px solid var(--line);border-radius:8px;padding:12px 9px;font-size:12px;font-weight:700;min-height:45px}.choice.active,.present.active{background:#fff0f2;border-color:var(--red);color:#a4142d}.presentrow{display:grid;grid-template-columns:1fr 1fr;gap:9px}.present{text-align:left;min-height:97px;display:flex;flex-direction:column;align-items:start;justify-content:space-between}.present small{font-size:10px;color:#777;line-height:1.5}.qty{display:inline-flex;border:1px solid var(--line);border-radius:9px;overflow:hidden;align-items:center}.qty button{border:0;background:#f7f7f8;padding:11px 16px;font-size:20px}.qty span{width:60px;text-align:center;font-size:17px;font-weight:800}.bottom{border-top:1px solid var(--line);padding-top:18px;margin-top:20px;display:flex;justify-content:space-between;align-items:center;gap:10px}.muted{color:var(--mute);font-size:12px}.primary{background:var(--ink);color:white;border:0;border-radius:9px;padding:15px 17px;font-size:12px;font-weight:800}.warning{background:#f8f2f3;color:#a01830;font-size:11px;padding:11px;border-radius:8px;margin:18px 0;line-height:1.6}.cart{position:fixed;inset:0;z-index:25;display:none;background:#10121699;justify-content:flex-end}.cart.open{display:flex}.drawer{background:white;width:min(440px,100vw);height:100dvh;padding:24px;overflow:auto}.cartitem{padding:15px 0;border-bottom:1px solid var(--line)}.cartitem strong{font-size:13px}.cartitem p{color:var(--mute);font-size:12px;margin:5px 0}.cartitem button{border:0;background:none;color:#b91f39;font-size:11px;padding:0}.empty{text-align:center;color:var(--mute);padding:60px 10px}.summary{font-size:13px;line-height:1.8}.mobilecart{display:none}.deskhide{display:none}
@media(max-width:700px){.wrap{padding:0 17px}.headinner{height:67px}.logo{font-size:27px}.hero{grid-template-columns:1fr;padding:42px 0 20px;gap:17px}.hero h1{font-size:43px;letter-spacing:-1.4px}.hero p{font-size:13px}.heroart{min-height:145px}.heroart strong{font-size:115px}.sectiontitle h2{font-size:25px}.filters{flex-wrap:wrap}.search{flex-basis:100%;order:-1}.cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.pic{height:130px;font-size:50px}.info{padding:13px}.info h3{font-size:14px;line-height:1.4;min-height:59px}.info button{padding:12px 10px}.overlay{align-items:flex-end;padding:0}.dialog{border-radius:16px 16px 0 0;max-height:92dvh;width:100%;padding:19px}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.choice{font-size:11px;padding:11px 6px}.present{min-height:105px}.footer{padding:30px 0}.mobilecart{display:block;position:fixed;bottom:14px;left:14px;right:14px;background:var(--ink);color:white;border:0;padding:16px;border-radius:10px;z-index:5;font-weight:800;font-size:13px}}
</style></head><body><div class="notice">VISTA PREVIA INTERACTIVA · Sin precios, stock ni cobros reales</div><header class="head"><div class="wrap headinner"><div class="logo">JC<span>.</span><small>SOLUCIONES DESCARTABLES</small></div><button onclick="openCart()">Mi carrito · <b id="count">0</b></button></div></header>
<main class="wrap"><section class="hero"><div><div class="kicker">CATÁLOGO JC</div><h1>Todo para tu negocio.<br/><em>En un solo lugar.</em></h1><p>Elegí el producto, la medida y la presentación. Compra por bulto o individual, con precios y stock sincronizados cuando conectemos el ERP.</p></div><div class="heroart"><strong>JC</strong><small>CATÁLOGO EN PREPARACIÓN</small></div></section><div class="sectiontitle"><div><div class="kicker">PRIMERA ETAPA</div><h2>Productos seleccionados.</h2></div><span id="counter"></span></div><div class="filters"><input class="search" id="search" placeholder="Buscar marca, medida o SKU" oninput="render()"/><button id="all" class="on" onclick="filterBy('Todos')">Todos</button><button id="ar" onclick="filterBy('Arranques')">Arranques</button><button id="pap" onclick="filterBy('Papel')">Papel</button></div><div class="cards" id="cards"></div></main><footer class="footer"><div class="wrap"><div class="logo">JC<span>.</span></div><p>Esta es una vista previa. Los artículos no están publicados ni admiten pagos todavía.</p></div></footer>
<div class="overlay" id="overlay" onclick="if(event.target===this)closeModal()"><div class="dialog"><div class="dialoghead"><div><div class="kicker">ELEGIR VARIANTE</div><h2 id="title"></h2></div><button class="close" onclick="closeModal()">×</button></div><div class="field"><h4>1. Medida o modelo</h4><div class="grid" id="variants"></div></div><div class="field"><h4>2. Presentación</h4><div class="presentrow" id="presentations"></div></div><div class="field"><h4>3. Cantidad</h4><div class="qty"><button onclick="qtyChange(-1)">−</button><span id="qty">1</span><button onclick="qtyChange(1)">+</button></div></div><div class="warning">Los costos del PDF son internos. No se muestra ni inventa el precio de venta. El stock real se carga desde JC Gestión.</div><div class="bottom"><span class="muted">Precio de venta pendiente</span><button class="primary" onclick="addCart()">Agregar a prueba →</button></div></div></div>
<div class="cart" id="cart" onclick="if(event.target===this)closeCart()"><div class="drawer"><div class="dialoghead"><div><div class="kicker">PRUEBA DEL CARRITO</div><h2>Mi carrito</h2></div><button class="close" onclick="closeCart()">×</button></div><div id="cartcontent"></div><div class="warning">Pago desactivado: todavía no hay precios ni existencias reales. El proyecto Next.js incluye la integración preparada con Mercado Pago.</div><button class="primary" style="width:100%" disabled>Finalizar pedido · No habilitado</button></div></div><button class="mobilecart" onclick="openCart()">Ver carrito · <span id="mobilecount">0</span></button>
<script>const groups=__GROUPS__;let category='Todos',current=-1,selectedSku=0,selectedPresentation='pack',quantity=1,cart=[];
const $=s=>document.querySelector(s);const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filterBy(t){category=t;$('#all').classList.toggle('on',t==='Todos');$('#ar').classList.toggle('on',t==='Arranques');$('#pap').classList.toggle('on',t==='Papel');render()}
function render(){let q=$('#search').value.toLowerCase();let count=0;$('#cards').innerHTML=groups.map((g,i)=>{if(category!=='Todos'&&category!==g.type)return '';if(!`${g.title} ${g.brand} ${g.variants.map(v=>v.sku+' '+v.label).join(' ')}`.toLowerCase().includes(q))return '';count++;return `<article class="card"><div class="pic">JC</div><div class="info"><span class="brand">${escapeHtml(g.brand)} · ${escapeHtml(g.type)}</span><h3>${escapeHtml(g.title)}</h3><p>${g.variants.length} variantes · Bulto o individual</p><button onclick="openGroup(${i})">Elegir opciones <span>→</span></button></div></article>`}).join('');$('#counter').textContent=count+' grupos';}
function openGroup(i){current=i;selectedSku=0;selectedPresentation='pack';quantity=1;$('#overlay').classList.add('open');renderModal()}
function closeModal(){$('#overlay').classList.remove('open')}
function renderModal(){let g=groups[current],v=g.variants[selectedSku];$('#title').textContent=g.title;$('#variants').innerHTML=g.variants.map((v,i)=>`<button class="choice ${i===selectedSku?'active':''}" onclick="selectedSku=${i};quantity=1;renderModal()">${escapeHtml(v.label)}</button>`).join('');$('#presentations').innerHTML=[['pack','Bulto cerrado',v.present,v.count],['unit','Individual',v.base,1]].map(([key,text,sub,num])=>`<button class="present ${selectedPresentation===key?'active':''}" onclick="selectedPresentation='${key}';quantity=1;renderModal()"><b>${escapeHtml(text)}</b><small>${escapeHtml(sub)}<br/>${num} ${escapeHtml(v.base)}</small></button>`).join('');$('#qty').textContent=quantity}
function qtyChange(n){quantity=Math.max(1,quantity+n);$('#qty').textContent=quantity}
function addCart(){let g=groups[current],v=g.variants[selectedSku],key=v.sku+':'+selectedPresentation;let old=cart.find(x=>x.key===key);if(old)old.qty+=quantity;else cart.push({key,group:g.title,variant:v.label,sku:v.sku,presentation:selectedPresentation==='pack'?v.present:'1 '+v.base,qty:quantity});closeModal();updateCart();openCart()}
function updateCart(){let n=cart.reduce((a,c)=>a+c.qty,0);$('#count').textContent=n;$('#mobilecount').textContent=n;$('#cartcontent').innerHTML=cart.length?cart.map((x,i)=>`<div class="cartitem"><strong>${escapeHtml(x.group)}</strong><p>${escapeHtml(x.variant)} · ${escapeHtml(x.presentation)} · ${x.qty} cantidad(es)</p><p>${escapeHtml(x.sku)}</p><button onclick="cart.splice(${i},1);updateCart()">Eliminar</button></div>`).join('')+'<p class="summary">Precio y stock: pendientes de carga en JC Gestión.</p>':'<p class="empty">Todavía no agregaste artículos.</p>'}
function openCart(){$('#cart').classList.add('open');updateCart()}
function closeCart(){$('#cart').classList.remove('open')}
render();updateCart();</script></body></html>'''
page=page.replace('__GROUPS__',J)
(root.parent/'JC_Tienda_Vista_Previa.html').write_text(page,encoding='utf-8')
print('Vista previa:',sum(len(g['variants']) for g in groups),'SKU',len(groups),'grupos')
